static unsigned char *P[NSLOTS];
static size_t N[NSLOTS];
static unsigned SEED[NSLOTS];
static unsigned char *DP[NDANGLE];

static unsigned char pat(unsigned seed, size_t i) {
    return (unsigned char)(seed * 131u + i * 7u + (i >> 8) * 13u);
}
static void fill(unsigned char *p, size_t n, unsigned seed) {
    for (size_t i = 0; i < n; i++) p[i] = pat(seed, i);
}
static int same(const unsigned char *p, size_t n, unsigned seed) {
    for (size_t i = 0; i < n; i++)
        if (p[i] != pat(seed, i)) return 0;
    return 1;
}
static int zero(const unsigned char *p, size_t n) {
    for (size_t i = 0; i < n; i++)
        if (p[i]) return 0;
    return 1;
}

int main(void) {
    size_t nops = sizeof OPS / sizeof OPS[0];
    for (size_t k = 0; k < nops; k++) {
        const unsigned long long *o = OPS[k];
        int s = (int)o[1];
        unsigned char *q;
        switch ((int)o[0]) {
        case OP_MALLOC:
            q = my_malloc((size_t)o[2]);
            if ((q == NULL) != (o[5] != 0)) printf("BAD RESULT op %zu\n", k);
            if (q) { P[s] = q; N[s] = (size_t)o[2]; SEED[s] = (unsigned)o[3]; fill(q, N[s], SEED[s]); }
            break;
        case OP_CALLOC:
            q = my_calloc((size_t)o[2], (size_t)o[3]);
            if ((q == NULL) != (o[5] != 0)) printf("BAD RESULT op %zu\n", k);
            if (q) {
                N[s] = (size_t)o[2] * (size_t)o[3];
                if (!zero(q, N[s])) printf("NOT ZERO op %zu\n", k);
                P[s] = q; SEED[s] = (unsigned)o[4]; fill(q, N[s], SEED[s]);
            }
            break;
        case OP_REALLOC: {
            unsigned char *old = P[s];
            size_t oldn = N[s], n = (size_t)o[2];
            if (old && !same(old, oldn, SEED[s])) printf("CORRUPT before realloc op %zu\n", k);
            q = my_realloc(old, n);
            if ((q == NULL) != (o[5] != 0)) printf("BAD RESULT op %zu\n", k);
            if (o[4] != ~0ULL) DP[o[4]] = old;
            if (q) {
                size_t m = oldn < n ? oldn : n;
                if (old && !same(q, m, SEED[s])) printf("CORRUPT after realloc op %zu\n", k);
                P[s] = q; N[s] = n; SEED[s] = (unsigned)o[3]; fill(q, n, SEED[s]);
            } else if (n == 0) {
                P[s] = NULL; N[s] = 0;
            } else if (old && !same(old, oldn, SEED[s])) {
                printf("CORRUPT after failed realloc op %zu\n", k);
            }
            break;
        }
        case OP_FREE:
            if (!same(P[s], N[s], SEED[s])) printf("CORRUPT before free op %zu\n", k);
            if (o[4] != ~0ULL) DP[o[4]] = P[s];
            my_free(P[s]);
            P[s] = NULL; N[s] = 0;
            break;
        case OP_POLICY: my_set_policy((int)o[2]); break;
        case OP_DELAY: my_set_delay((int)o[2]); break;
        case OP_DUMP: my_heap_dump(); break;
        case OP_LEAK: my_leak_report(); break;
        case OP_CORRUPT: P[s][N[s] + (size_t)o[2]] = 0x5A; break;
        case OP_WAF: DP[o[2]][(size_t)o[3]] = 'X'; break;
        case OP_STALE_FREE: my_free(DP[o[2]]); break;
        case OP_STALE_REALLOC:
            if (my_realloc(DP[o[2]], (size_t)o[3]) != NULL) printf("BAD RESULT op %zu\n", k);
            break;
        case OP_INT_FREE: my_free(P[s] + (size_t)o[2]); break;
        case OP_INT_REALLOC:
            if (my_realloc(P[s] + (size_t)o[2], (size_t)o[3]) != NULL) printf("BAD RESULT op %zu\n", k);
            break;
        case OP_CHECKALL:
            for (int i = 0; i < NSLOTS; i++)
                if (P[i] && !same(P[i], N[i], SEED[i])) printf("CORRUPT slot %d op %zu\n", i, k);
            break;
        }
    }
    return 0;
}
